export type PromptId = keyof typeof promptTemplates;

export function renderSystemPrompt(
  id: PromptId,
  variables: Record<string, string | number> = {},
) {
  return promptTemplates[id].replace(
    /\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g,
    (_match, key: string) => {
      const value = variables[key];
      if (value === undefined) {
        throw new Error("Missing prompt variable " + key + " for " + id);
      }
      return String(value);
    },
  );
}
